/**
 * Character classes that mirror Python's `re` module semantics for `str`
 * patterns, so that tokenizing and tagging behave identically.
 *
 * Python's `\w` is `str.isalnum() or "_"`, i.e. Unicode categories L*, Nd, Nl,
 * No plus the underscore.  Python's `\s` is `str.isspace()`, which includes the
 * ASCII separators \x1c-\x1f and \x85 but not the byte order mark.
 */
export const WORD_CLASS = "[\\p{L}\\p{Nd}\\p{Nl}\\p{No}_]";

export const SPACE_CLASS =
  "[\\t\\n\\v\\f\\r\\x1c\\x1d\\x1e\\x1f\\x20\\x85\\u00a0\\u1680" +
  "\\u2000-\\u200a\\u2028\\u2029\\u202f\\u205f\\u3000]";

/** Number of code points in `text` (Python's `len()` for `str`). */
export function codePointLength(text) {
  let n = 0;
  for (const _ of text) n += 1;
  return n;
}

/** Array of code points, used for Python-like string ordering. */
export function codePoints(text) {
  const out = [];
  for (const ch of text) out.push(ch.codePointAt(0));
  return out;
}

/**
 * Compares two strings by code point, the way Python compares `str` values
 * (and the way the reference index compares its UTF-8 encoded terms).
 */
export function compareText(a, b) {
  if (a === b) return 0;
  const ca = codePoints(a);
  const cb = codePoints(b);
  const n = Math.min(ca.length, cb.length);
  for (let i = 0; i < n; i += 1) {
    if (ca[i] !== cb[i]) return ca[i] < cb[i] ? -1 : 1;
  }
  return ca.length === cb.length ? 0 : (ca.length < cb.length ? -1 : 1);
}

/**
 * Builds a sticky regular expression: `exec()` then only matches at the exact
 * offset assigned to `lastIndex`, which is how Python's `pattern.match(text,
 * pos)` behaves (lookbehind may still inspect earlier text).
 */
export function anchoredRegExp(source, flags = "") {
  return new RegExp(source, `${flags.replace(/[gy]/g, "")}uy`);
}

