import { STOP_WORDS } from "./stopwords.mjs";
import { WORD_CLASS, codePointLength } from "./pyregex.mjs";

/** A single analyzed token: its text plus its position in the field. */
export class Token {
  constructor(text, pos) {
    this.text = text;
    this.pos = pos;
    this.stopped = false;
  }
}

/** Default tokenizer expression: `\w+(\.?\w+)*` with Unicode word characters. */
export const DEFAULT_PATTERN = new RegExp(
  `${WORD_CLASS}+(\\.?${WORD_CLASS}+)*`,
  "gu",
);

/**
 * Splits `value` into tokens on the default expression.  When `tokenize` is
 * false the whole value becomes a single token, which is what query nodes that
 * must not be broken up (wildcards, ranges) rely on.
 */
export function regexTokenizer(value, { tokenize = true, startPos = 0 } = {}) {
  if (!tokenize) return [new Token(value, startPos)];

  const re = new RegExp(DEFAULT_PATTERN.source, "gu");
  const tokens = [];
  let pos = startPos;
  let match;
  while ((match = re.exec(value)) !== null) {
    tokens.push(new Token(match[0], pos));
    pos += 1;
    if (match[0].length === 0) re.lastIndex += 1;
  }
  return tokens;
}

/** Lowercases every token in place. */
export function lowercaseFilter(tokens) {
  for (const token of tokens) token.text = token.text.toLowerCase();
  return tokens;
}

/**
 * Drops stop words and tokens outside the size limits.  Surviving tokens are
 * renumbered so that the gaps left by removed words disappear (the first
 * survivor keeps its original position), which is what makes phrase queries
 * match across stop words.
 *
 * With `removestops` false the tokens are kept and merely flagged, which is how
 * non-tokenized query text keeps short or stop-worded values intact.
 */
export function stopFilter(
  tokens,
  {
    stoplist = STOP_WORDS,
    minsize = 2,
    maxsize = null,
    removestops = true,
    renumber = true,
  } = {},
) {
  const out = [];
  let pos = null;
  for (const token of tokens) {
    const size = codePointLength(token.text);
    const keep =
      size >= minsize &&
      (maxsize === null || size <= maxsize) &&
      !stoplist.has(token.text);
    if (keep) {
      if (renumber) {
        pos = pos === null ? token.pos : pos + 1;
        token.pos = pos;
      }
      token.stopped = false;
      out.push(token);
    } else if (!removestops) {
      token.stopped = true;
      out.push(token);
    }
  }
  return out;
}

/**
 * The standard analyzer: tokenize on word characters, lowercase, then remove
 * stop words and one-character tokens.
 */
export function standardAnalyzer(
  value,
  { tokenize = true, removestops = true } = {},
) {
  let tokens = regexTokenizer(value, { tokenize });
  tokens = lowercaseFilter(tokens);
  return stopFilter(tokens, { removestops });
}

