import { standardAnalyzer } from "./analysis/analyzer.mjs";

/** Base class for schema field types. */
class FieldType {
  constructor({ stored = false } = {}) {
    this.stored = stored;
    this.format = true;
    this.phrase = true;
  }

  /** True for field types that parse their own query strings (none here). */
  selfParsing() {
    return false;
  }

  /** Analyzes text and returns the resulting token texts. */
  processText(text, { tokenize = true, removestops = true } = {}) {
    return standardAnalyzer(text, { tokenize, removestops }).map((t) => t.text);
  }

  /** Analyzes a field value into a `term -> positions` map. */
  index(value) {
    const terms = new Map();
    for (const token of standardAnalyzer(value)) {
      let positions = terms.get(token.text);
      if (positions === undefined) {
        positions = [];
        terms.set(token.text, positions);
      }
      positions.push(token.pos);
    }
    return terms;
  }
}

/** Analyzed, position-aware text field. */
export class TEXT extends FieldType {}

/** Single-token identifier field: stored verbatim, never analyzed. */
export class ID extends FieldType {
  constructor(options = {}) {
    super(options);
    this.phrase = false;
  }

  processText(text) {
    return [text];
  }

  index(value) {
    return new Map([[value, [0]]]);
  }
}

/**
 * A collection of named fields.  Construct it with plain field instances:
 * `new Schema({ title: new TEXT({ stored: true }), content: new TEXT() })`.
 */
export class Schema {
  constructor(fields = {}) {
    this.fields = new Map(Object.entries(fields));
  }

  has(name) {
    return this.fields.has(name);
  }

  get(name) {
    return this.fields.get(name);
  }

  names() {
    return [...this.fields.keys()];
  }
}

