import { mkdtempSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

import { compareText } from "./analysis/pyregex.mjs";
import { Searcher } from "./searching.mjs";

/**
 * Read-only view over an index: term dictionaries, postings and document ids.
 */
export class IndexReader {
  constructor(schema, docCount, fieldIndexes) {
    this.schema = schema;
    this._docCount = docCount;
    // fieldname -> Map(term -> Map(docnum -> positions[]))
    this._fields = fieldIndexes;
    this._lexicons = new Map();
  }

  docCount() {
    return this._docCount;
  }

  allDocIds() {
    const ids = [];
    for (let i = 0; i < this._docCount; i += 1) ids.push(i);
    return ids;
  }

  /** Sorted list of every term indexed in a field. */
  lexicon(fieldname) {
    if (!this._fields.has(fieldname)) return [];
    let terms = this._lexicons.get(fieldname);
    if (terms === undefined) {
      terms = [...this._fields.get(fieldname).keys()].sort(compareText);
      this._lexicons.set(fieldname, terms);
    }
    return terms;
  }

  /** `Map(docnum -> positions)` for a term, or null when the term is absent. */
  postings(fieldname, term) {
    const field = this._fields.get(fieldname);
    if (field === undefined) return null;
    return field.get(term) ?? null;
  }

  /** Documents that have at least one term in the given field. */
  fieldDocs(fieldname) {
    const docs = new Set();
    const field = this._fields.get(fieldname);
    if (field === undefined) return docs;
    for (const postings of field.values()) {
      for (const docnum of postings.keys()) docs.add(docnum);
    }
    return docs;
  }
}

/** Accumulates documents and publishes them to the index on commit. */
export class IndexWriter {
  constructor(index) {
    this._index = index;
    this._pending = [];
    this._committed = false;
  }

  addDocument(fields) {
    if (this._committed) throw new Error("writer is already committed");
    this._pending.push(fields);
  }

  commit() {
    for (const fields of this._pending) this._index._addDocument(fields);
    this._pending = [];
    this._committed = true;
  }
}

/** An index: a schema plus the inverted index built from added documents. */
export class Index {
  constructor(schema, directory = null) {
    this.schema = schema;
    this.directory = directory;
    this._docCount = 0;
    this._fields = new Map();
    for (const name of schema.names()) this._fields.set(name, new Map());
  }

  writer() {
    return new IndexWriter(this);
  }

  reader() {
    return new IndexReader(this.schema, this._docCount, this._fields);
  }

  searcher() {
    return new Searcher(this.reader());
  }

  _addDocument(fields) {
    const docnum = this._docCount;
    this._docCount += 1;
    for (const [name, value] of Object.entries(fields)) {
      const fieldtype = this.schema.get(name);
      if (fieldtype === undefined) {
        throw new Error(`No field named ${name} in the schema`);
      }
      const dictionary = this._fields.get(name);
      for (const [term, positions] of fieldtype.index(String(value))) {
        let postings = dictionary.get(term);
        if (postings === undefined) {
          postings = new Map();
          dictionary.set(term, postings);
        }
        postings.set(docnum, positions);
      }
    }
  }
}

/** Creates an index inside `dirname` (mirrors the on-disk API of the source). */
export function createIn(dirname, schema) {
  return new Index(schema, dirname);
}

/** Creates a fresh temporary directory, as the source program does. */
export function makeTempDir(prefix = "whoosh-") {
  return mkdtempSync(join(tmpdir(), prefix));
}

