/**
 * Port of Python's `fnmatch.translate()`, which is what the reference wildcard
 * query uses to expand a glob over the term dictionary.
 *
 * Supported syntax: `*` (any run of characters), `?` (exactly one character)
 * and `[seq]` / `[!seq]` character classes.  An unterminated `[` is literal.
 */
function escapeLiteral(ch) {
  if (/^[A-Za-z0-9_]$/.test(ch)) return ch;
  const code = ch.codePointAt(0);
  if (code < 0x80) return `\\x${code.toString(16).padStart(2, "0")}`;
  // Non-ASCII characters are never regex metacharacters.
  return ch;
}

function escapeClassBody(body) {
  let out = "";
  for (const ch of body) {
    if (ch === "\\" || ch === "]" || ch === "^") out += `\\${ch}`;
    else if (ch === "-") out += "-";
    else out += escapeLiteral(ch);
  }
  return out;
}

/** Translates a glob pattern into an equivalent regular expression source. */
export function translate(pattern) {
  const chars = [...pattern];
  const parts = [];
  let i = 0;
  const n = chars.length;

  while (i < n) {
    const ch = chars[i];
    i += 1;
    if (ch === "*") {
      if (parts[parts.length - 1] !== ".*") parts.push(".*");
    } else if (ch === "?") {
      parts.push(".");
    } else if (ch === "[") {
      let j = i;
      if (j < n && chars[j] === "!") j += 1;
      if (j < n && chars[j] === "]") j += 1;
      while (j < n && chars[j] !== "]") j += 1;
      if (j >= n) {
        parts.push("\\[");
      } else {
        let body = chars.slice(i, j).join("");
        i = j + 1;
        if (body === "") {
          parts.push("(?!)");
        } else if (body === "!") {
          parts.push(".");
        } else {
          let negated = false;
          if (body.startsWith("!")) {
            negated = true;
            body = body.slice(1);
          }
          parts.push(`[${negated ? "^" : ""}${escapeClassBody(body)}]`);
        }
      }
    } else {
