 * simplest equivalent query and how to report the set of documents it matches.
 */
export class Query {
  constructor() {
    this.boost = 1.0;
  }

  normalize() {
    return this;
  }

  /** Returns a `Set` of matching document numbers. */
  docs(_reader) {
    throw new Error("docs() is not implemented");
  }

  isNull() {
    return false;
  }
}

class NullQueryType extends Query {
  normalize() {
    return this;
  }

  docs() {
    return new Set();
  }

  isNull() {
    return true;
  }
}

/** The query that matches nothing; a single shared instance, as in the source. */
export const NullQuery = new NullQueryType();

/** Matches documents containing an exact term in a field. */
export class Term extends Query {
  constructor(fieldname, text) {
    super();
    this.fieldname = fieldname;
    this.text = text;
  }

  docs(reader) {
    const postings = reader.postings(this.fieldname, this.text);
    return postings === null ? new Set() : new Set(postings.keys());
  }
}

/** Matches every document, or every document with a value in one field. */
export class Every extends Query {
  constructor(fieldname = null) {
    super();
    this.fieldname = fieldname;
  }

  docs(reader) {
    if (this.fieldname === null || this.fieldname === "" || this.fieldname === "*") {
      return new Set(reader.allDocIds());
    }
    return reader.fieldDocs(this.fieldname);
  }
}

/** Base class for queries expanded over the terms of a field. */
class MultiTerm extends Query {
  constructor(fieldname) {
    super();
    this.fieldname = fieldname;
  }

  /** Terms of the field this query expands to. */
  terms(_reader) {
    return [];
  }

  docs(reader) {
    const found = new Set();
    for (const term of this.terms(reader)) {
      const postings = reader.postings(this.fieldname, term);
      if (postings === null) continue;
      for (const docnum of postings.keys()) found.add(docnum);
    }
    return found;
  }
}

/** Matches documents with any term starting with the given text. */
export class Prefix extends MultiTerm {
  constructor(fieldname, text) {
    super(fieldname);
    this.text = text;
  }

  terms(reader) {
    return reader.lexicon(this.fieldname).filter((t) => t.startsWith(this.text));
  }
}

/** Matches documents with any term matching a glob pattern. */
export class Wildcard extends MultiTerm {
  constructor(fieldname, text) {
    super(fieldname);
    this.text = text;
  }

  normalize() {
    const text = this.text;
    if (text === "*") return new Every(this.fieldname);
    if (!text.includes("*") && !text.includes("?")) {
      return new Term(this.fieldname, text);
    }
    if (!text.includes("?") && text.endsWith("*") && text.indexOf("*") === text.length - 1) {
      return new Prefix(this.fieldname, text.slice(0, -1));
    }
    return this;
  }

  terms(reader) {
    const expression = compileGlob(this.text);
    return reader.lexicon(this.fieldname).filter((t) => expression.test(t));
  }
}

/** Matches documents with any term inside a range of terms. */
export class TermRange extends MultiTerm {
  constructor(fieldname, start, end, startexcl = false, endexcl = false) {
    super(fieldname);
    this.start = start;
    this.end = end;
    this.startexcl = startexcl;
    this.endexcl = endexcl;
  }

  normalize() {
    const startEmpty = this.start === null || this.start === "";
    const endEmpty = this.end === null || this.end === "￿";
    if (startEmpty && endEmpty) return new Every(this.fieldname);
    if (this.start !== null && this.start === this.end) {
      if (this.startexcl || this.endexcl) return NullQuery;
      return new Term(this.fieldname, this.start);
    }
    return this;
  }

  terms(reader) {
    return reader.lexicon(this.fieldname).filter((text) => {
      if (this.start !== null) {
        const cmp = compareText(text, this.start);
        if (cmp < 0 || (cmp === 0 && this.startexcl)) return false;
      }
      if (this.end !== null) {
        const cmp = compareText(text, this.end);
        if (cmp > 0 || (cmp === 0 && this.endexcl)) return false;
      }
      return true;
    });
  }
}

/** Matches documents where the given words appear in order and close together. */
export class Phrase extends Query {
  constructor(fieldname, words, slop = 1) {
    super();
    this.fieldname = fieldname;
    this.words = words;
    this.slop = slop;
  }

  normalize() {
    if (this.words.length === 0) return NullQuery;
    if (this.words.length === 1) return new Term(this.fieldname, this.words[0]);
