    const postingsList = this.words.map((word) =>
      reader.postings(this.fieldname, word),
    );
    if (postingsList.some((p) => p === null)) return new Set();

    const candidates = [...postingsList[0].keys()].filter((docnum) =>
      postingsList.every((p) => p.has(docnum)),
    );

    const found = new Set();
    for (const docnum of candidates) {
      let reachable = [...postingsList[0].get(docnum)];
      for (let i = 1; i < postingsList.length; i += 1) {
        const positions = postingsList[i].get(docnum);
        const next = positions.filter((pos) =>
          reachable.some((prev) => pos - prev > 0 && pos - prev <= this.slop),
        );
