/**
 * Search results: the ordered list of matching document numbers together with
 * the total number of matches (`length`, the value the source program prints).
 */
export class Results {
  constructor(docnums) {
    this.docnums = docnums;
  }

  get length() {
    return this.docnums.length;
  }

  [Symbol.iterator]() {
    return this.docnums[Symbol.iterator]();
  }
}

/** Runs queries against an index reader. */
export class Searcher {
  constructor(reader) {
    this.reader = reader;
  }

  get schema() {
    return this.reader.schema;
  }

  /**
   * Executes a query.  `limit` caps how many documents are collected, matching
   * the default of the source API.
   */
  search(query, { limit = 10 } = {}) {
    const docnums = [...query.docs(this.reader)].sort((a, b) => a - b);
    const collected = limit === null ? docnums : docnums.slice(0, limit);
    return new Results(collected);
  }
}

