    this.hasFieldname = false;
    this.hasBoost = false;
    this.original = null;
  }

  isText() {
    return false;
  }

  isWhitespace() {
    return false;
  }

  setFieldname(name, override = false) {
    if (!this.hasFieldname) return this;
    if (this.fieldname === null || override) this.fieldname = name;
    return this;
  }

  setBoost(boost) {
    if (this.hasBoost) this.boost = boost;
    return this;
  }

  query(_parser) {
    return NullQuery;
  }
}

/** Base class for nodes carrying literal text. */
export class TextNode extends SyntaxNode {
  constructor(text) {
    super();
    this.text = text;
    this.hasFieldname = true;
    this.hasBoost = true;
    this.tokenize = false;
    this.removestops = false;
    this.qclass = null;
  }

  isText() {
    return true;
  }

  setText(text) {
    this.text = text;
  }

  query(parser) {
    const fieldname = this.fieldname ?? parser.fieldname;
    return parser.termQuery(fieldname, this.text, this.qclass ?? Term, {
      tokenize: this.tokenize,
      removestops: this.removestops,
    });
  }
}

/** A plain search word; its text is analyzed like document text. */
export class WordNode extends TextNode {
  constructor(text) {
    super(text);
    this.tokenize = true;
    this.removestops = true;
  }
}

/** A glob pattern; its text is passed to the query untokenized. */
export class WildcardNode extends TextNode {
  constructor(text) {
    super(text);
    this.qclass = Wildcard;
  }
}

/** A "starts with" pattern; its text is passed to the query untokenized. */
export class PrefixNode extends TextNode {
  constructor(text) {
    super(text);
    this.qclass = Prefix;
  }
}

/** A quoted phrase, optionally with a slop suffix. */
export class PhraseNode extends TextNode {
  constructor(text, slop = 1) {
    super(text);
    this.slop = slop;
  }

  query(parser) {
    const fieldname = this.fieldname ?? parser.fieldname;
    const field = parser.schema ? parser.schema.get(fieldname) : undefined;
    const words = field ? field.processText(this.text) : this.text.split(/\s+/).filter(Boolean);
    return new Phrase(fieldname, words, this.slop);
  }
}

/** A range of terms, `[start TO end]` or `{start TO end}`. */
export class RangeNode extends SyntaxNode {
  constructor(start, end, startexcl, endexcl) {
    super();
    this.start = start;
    this.end = end;
    this.startexcl = startexcl;
    this.endexcl = endexcl;
    this.hasFieldname = true;
    this.hasBoost = true;
  }

  query(parser) {
    const fieldname = this.fieldname ?? parser.fieldname;
    let { start, end } = this;
    const field = parser.schema ? parser.schema.get(fieldname) : undefined;
    if (field !== undefined) {
      if (start) start = parser.singleText(field, start);
      if (end) end = parser.singleText(field, end);
    }
    return new TermRange(fieldname, start ?? null, end ?? null, this.startexcl, this.endexcl);
  }
}

/** The `*:*` marker: matches every document in the index. */
export class EveryNode extends SyntaxNode {
  constructor() {
    super();
    this.hasBoost = true;
  }

  query() {
    return new Every();
  }
}

/** A `fieldname:` marker, applied to the node that follows it. */
export class FieldnameNode extends SyntaxNode {
  constructor(fieldname, original) {
    super();
    this.fieldname = fieldname;
    this.original = original;
  }
}

/** A run of whitespace; removed before operators are resolved. */
export class Whitespace extends SyntaxNode {
  isWhitespace() {
    return true;
  }
}

/** A `^boost` marker, applied to the node before it. */
export class BoostNode extends SyntaxNode {
  constructor(original, boost) {
    super();
    this.original = original;
    this.boost = boost;
  }
}

export class OpenBracket extends SyntaxNode {}
export class CloseBracket extends SyntaxNode {}

/** Turns a marker node back into a searchable word (its original text). */
export function toWord(node) {
  const word = new WordNode(node.original ?? "");
  word.startchar = node.startchar;
  word.endchar = node.endchar;
  return word;
}

/** A sequence of nodes; the group type decides how they are combined. */
export class GroupNode extends SyntaxNode {
  constructor(nodes = []) {
    super();
    this.nodes = nodes;
    this.merging = true;
    this.qclass = null;
    this.hasFieldname = true;
    this.hasBoost = true;
  }

  get length() {
    return this.nodes.length;
  }

  emptyCopy() {
    const copy = new this.constructor([]);
    copy.fieldname = this.fieldname;
    copy.boost = this.boost;
    return copy;
  }

  setFieldname(name, override = false) {
    super.setFieldname(name, override);
    for (const node of this.nodes) node.setFieldname(name, override);
    return this;
  }

  query(parser) {
    const subqueries = this.nodes.map((node) => node.query(parser));
    return new this.qclass(subqueries);
  }
}

/** Default group: every clause must match. */
export class AndGroup extends GroupNode {
  constructor(nodes = []) {
    super(nodes);
    this.qclass = And;
  }
}

/** Any clause may match. */
export class OrGroup extends GroupNode {
  constructor(nodes = []) {
    super(nodes);
    this.qclass = Or;
  }
}

/** Group holding exactly one negated clause. */
export class NotGroup extends GroupNode {
  constructor(nodes = []) {
    super(nodes);
    this.merging = false;
    this.qclass = Not;
  }

  query(parser) {
    // Indexing the missing clause of a malformed "NOT NOT x" raises, exactly as
    // the source program does.
    return new Not(this.nodes.at(0).query(parser));
  }
}

/** Base class for the two-sided operator groups. */
class BinaryGroup extends GroupNode {
  constructor(nodes = []) {
    super(nodes);
    this.merging = false;
    this.hasBoost = false;
  }

  query(parser) {
    const qa = this.nodes.at(0).query(parser);
    const qb = this.nodes.at(1).query(parser);
    return new this.qclass(qa, qb);
  }
}

export class AndNotGroup extends BinaryGroup {
  constructor(nodes = []) {
    super(nodes);
    this.qclass = AndNot;
  }
}

export class AndMaybeGroup extends BinaryGroup {
  constructor(nodes = []) {
    super(nodes);
    this.qclass = AndMaybe;
  }
}

export class RequireGroup extends BinaryGroup {
  constructor(nodes = []) {
    super(nodes);
    this.qclass = Require;
  }
}

/**
 * Operators rewrite the node stream around them into a group.  A prefix
 * operator wraps the node that follows it; an infix operator combines the node
 * before it with the node after it.
 */
export class Operator extends SyntaxNode {
  constructor(text, grouptype) {
    super();
    this.text = text;
    this.grouptype = grouptype;
  }

  /** Rewrites `group` around this operator and returns the resume position. */
  replaceSelf(_parser, _group, _position) {
    throw new Error("replaceSelf() is not implemented");
  }
}

export class PrefixOperator extends Operator {
  replaceSelf(parser, group, position) {
    const nodes = group.nodes;
    nodes.splice(position, 1);
    if (position < nodes.length) {
      nodes[position] = new this.grouptype([nodes[position]]);
    }
    return position;
  }
}

export class InfixOperator extends Operator {
  constructor(text, grouptype, leftassoc = true) {
    super(text, grouptype);
    this.leftassoc = leftassoc;
  }

  replaceSelf(parser, group, position) {
    const nodes = group.nodes;
    if (position === 0 || position === nodes.length - 1) {
      // Nothing to join on one side: the operator simply disappears.
      nodes.splice(position, 1);
      return position;
    }

    const left = nodes[position - 1];
    const right = nodes[position + 1];
    if (this.leftassoc && left instanceof this.grouptype && left.merging) {
      left.nodes.push(right);
      nodes.splice(position, 2);
      return position - 1;
    }

    nodes.splice(position - 1, 3, new this.grouptype([left, right]));
    return position - 1;
  }
}

