import { SPACE_CLASS, WORD_CLASS, anchoredRegExp } from "../analysis/pyregex.mjs";
import {
  AndGroup,
  AndMaybeGroup,
  AndNotGroup,
  BoostNode,
  CloseBracket,
  EveryNode,
  FieldnameNode,
  GroupNode,
  InfixOperator,
  NotGroup,
  Operator,
  OpenBracket,
  OrGroup,
  PhraseNode,
  PrefixNode,
  PrefixOperator,
  RangeNode,
  RequireGroup,
  Whitespace,
  WildcardNode,
  WordNode,
  toWord,
} from "./syntax.mjs";

const NOT_WORD_BEFORE = `(?<!${WORD_CLASS})`;

/**
 * A tagger turns a stretch of query text at a given offset into a syntax node.
 * The expression is matched anchored at that offset, so lookbehind can still
 * inspect the preceding text.
 */
export class RegexTagger {
  constructor(source) {
    this.expression = anchoredRegExp(source);
  }

  match(parser, text, pos) {
    this.expression.lastIndex = pos;
    const found = this.expression.exec(text);
    if (found === null) return null;
    const node = this.create(parser, found);
    if (node === null) return null;
    node.startchar = pos;
    node.endchar = pos + found[0].length;
    return node;
  }

  create(_parser, _match) {
    return null;
  }
}

/** Tags runs of whitespace, which are dropped once operators are known. */
class WhitespaceTagger extends RegexTagger {
  constructor() {
    super(`${SPACE_CLASS}+`);
  }

  create() {
    return new Whitespace();
  }
}

/** Tags 'single quoted' text as one word, spaces included. */
class SingleQuoteTagger extends RegexTagger {
  constructor() {
    super(`${NOT_WORD_BEFORE}'(?<text>.*?)'(?=${SPACE_CLASS}|\\]|[)}]|$)`);
  }

  create(parser, match) {
    return new WordNode(match.groups.text);
  }
}

/** Tags a `fieldname:` prefix. */
class FieldsTagger extends RegexTagger {
  constructor() {
    super(`(?<text>${WORD_CLASS}+|[*]):`);
  }

  create(parser, match) {
    return new FieldnameNode(match.groups.text, match[0]);
  }
}

/** Tags a single wildcard character; neighbouring text is merged in later. */
class WildcardTagger extends RegexTagger {
  constructor() {
    super("[*?\\u055E\\u061F\\u1367]");
  }

  create() {
    return new WildcardNode("");
  }
}

/** Tags a "quoted phrase" with an optional ~slop suffix. */
class PhraseTagger extends RegexTagger {
  constructor() {
    super('"(?<text>.*?)"(~(?<slop>[1-9][0-9]*))?');
  }

  create(parser, match) {
    const slop = match.groups.slop ? Number.parseInt(match.groups.slop, 10) : 1;
    return new PhraseNode(match.groups.text, slop);
  }
}

/** Tags `[start TO end]` (inclusive) and `{start TO end}` (exclusive) ranges. */
class RangeTagger extends RegexTagger {
  constructor() {
    super(
      "(?<open>\\{|\\[)" +
        `(?<start>('[^']*?'${SPACE_CLASS}+)|([^\\]}]+?(?=[Tt][Oo])))?` +
        "[Tt][Oo]" +
        `(?<end>(${SPACE_CLASS}+'[^']*?')|([^\\]}]+?))?` +
        "(?<close>\\}|\\])",
    );
  }

  create(parser, match) {
    let start = match.groups.start ?? null;
    let end = match.groups.end ?? null;
    if (start) {
      start = start.replace(new RegExp(`${SPACE_CLASS}+$`, "u"), "");
      if (start.startsWith("'") && start.endsWith("'")) start = start.slice(1, -1);
    }
    if (end) {
      end = end.replace(new RegExp(`^${SPACE_CLASS}+`, "u"), "");
      if (end.startsWith("'") && end.endsWith("'")) end = end.slice(1, -1);
    }
    return new RangeNode(start, end, match.groups.open === "{", match.groups.close === "}");
  }
}

class OpenBracketTagger extends RegexTagger {
  constructor() {
    super("\\(");
  }

  create() {
    return new OpenBracket();
  }
}

class CloseBracketTagger extends RegexTagger {
  constructor() {
    super("\\)");
  }

  create() {
    return new CloseBracket();
  }
}

/** Tags a boolean operator keyword. */
class OperatorTagger extends RegexTagger {
  constructor(source, operator) {
    super(source);
    this.operator = operator;
  }

  create() {
    return this.operator;
  }
}

/** Tags a `^number` boost suffix. */
class BoostTagger extends RegexTagger {
  constructor() {
    super(`\\^(?<boost>[0-9]*(\\.[0-9]+)?)($|(?=[${SPACE_CLASS.slice(1, -1)})]))`);
  }

  create(parser, match) {
    const text = match[0];
    const boost = Number.parseFloat(match.groups.boost);
    if (Number.isNaN(boost)) {
      const word = new WordNode(text);
      word.original = text;
      return word;
    }
    return new BoostNode(text, boost);
  }
}

/** Tags `*:*`, the "every document" marker. */
class EveryTagger extends RegexTagger {
  constructor() {
    super("\\*:\\*");
  }

  create() {
    return new EveryNode();
  }
}

/** Recursively applies `visit` to every group in the tree, depth first. */
function forEachGroup(group, visit) {
  for (const node of group.nodes) {
    if (node instanceof GroupNode) forEachGroup(node, visit);
  }
  visit(group);
}

/** Turns bracketed stretches of nodes into nested groups. */
function doGroups(parser, group) {
  const stack = [parser.group()];
  for (const node of group.nodes) {
    if (node instanceof OpenBracket) {
      stack.push(parser.group());
    } else if (node instanceof CloseBracket) {
      if (stack.length > 1) {
        const last = stack.pop();
        stack[stack.length - 1].nodes.push(last);
      }
    } else {
      stack[stack.length - 1].nodes.push(node);
    }
  }

  let top = stack[0];
  for (const unclosed of stack.slice(1)) top.nodes.push(...unclosed.nodes);

  if (top.nodes.length === 1 && top.nodes[0] instanceof GroupNode) {
    const boost = top.boost;
    top = top.nodes[0];
    top.boost = boost;
  }
  return top;
}

/**
 * Merges the text nodes surrounding a wildcard character into a single pattern,
 * then rewrites patterns that are really just prefixes.
 */
function doWildcards(parser, group) {
  const nodes = group.nodes;
  let i = 0;
  while (i < nodes.length) {
    const node = nodes[i];
    if (node instanceof WildcardNode) {
      if (i < nodes.length - 1 && nodes[i + 1].isText()) {
        const next = nodes.splice(i + 1, 1)[0];
        node.text += next.text;
      }
      if (i > 0 && nodes[i - 1].isText()) {
        const previous = nodes.splice(i - 1, 1)[0];
        node.text = previous.text + node.text;
      } else {
        i += 1;
      }
    } else {
      if (node instanceof GroupNode) doWildcards(parser, node);
      i += 1;
    }
  }

  for (let j = 0; j < nodes.length; j += 1) {
    const node = nodes[j];
    if (!(node instanceof WildcardNode)) continue;
    const text = node.text;
    const hasQuestion = /[?՞؟፧]/u.test(text);
    if (text.length > 1 && !hasQuestion && text.indexOf("*") === text.length - 1) {
      const prefix = new PrefixNode(text.slice(0, -1));
      prefix.startchar = node.startchar;
      prefix.endchar = node.endchar;
      prefix.fieldname = node.fieldname;
      nodes[j] = prefix;
    }
  }
  return group;
}

/**
 * Resolves `fieldname:` markers.  Names that are not in the schema fold back
 * into the text that follows them; known names are applied to the very next
 * node (whitespace included, which is how "title: x" ends up unfielded).
 */
function doFieldnames(parser, group) {
  if (parser.schema) {
    const merged = [];
    let pending = null;
    for (const node of group.nodes) {
      if (node instanceof FieldnameNode && !parser.schema.has(node.fieldname)) {
        pending = node;
        continue;
      }
      if (pending !== null) {
        if (node.isText()) {
          node.setText(pending.original + node.text);
          node.startchar = pending.startchar;
        } else {
          merged.push(toWord(pending));
        }
        pending = null;
      }
      merged.push(node);
    }
    if (pending !== null) merged.push(toWord(pending));
    group.nodes = merged;
  }

  const kept = [];
  const nodes = group.nodes;
  for (let i = 0; i < nodes.length; i += 1) {
    const node = nodes[i];
    if (node instanceof FieldnameNode) {
      if (i + 1 < nodes.length) {
        nodes[i + 1].setFieldname(node.fieldname);
      } else {
        kept.push(toWord(node));
      }
      continue;
    }
    if (node instanceof GroupNode) doFieldnames(parser, node);
    kept.push(node);
  }
  group.nodes = kept;
  return group;
}

/** Drops whitespace nodes now that the plugins needing them have run. */
function removeWhitespace(parser, group) {
  const kept = [];
  for (const node of group.nodes) {
    if (node instanceof GroupNode) kept.push(removeWhitespace(parser, node));
    else if (!node.isWhitespace()) kept.push(node);
  }
  group.nodes = kept;
  return group;
}

/**
 * Rewrites operator nodes into groups.  Operators are resolved one kind at a
 * time, in the order they are configured, so that earlier kinds bind tighter:
 * NOT, then AND, then OR, then ANDNOT / ANDMAYBE / REQUIRE.
 */
function doOperators(parser, group) {
  for (const operator of parser.operators) {
    let i = 0;
    while (i < group.nodes.length) {
      if (group.nodes[i] === operator) {
        i = operator.replaceSelf(parser, group, i);
      } else {
        i += 1;
      }
    }
  }
  for (const node of group.nodes) {
    if (node instanceof GroupNode) doOperators(parser, node);
  }
  return group;
}

/** Turns boost markers that have nothing to boost back into words. */
function cleanBoost(parser, group) {
  forEachGroup(group, (current) => {
    const nodes = current.nodes;
    for (let i = 0; i < nodes.length; i += 1) {
      if (nodes[i] instanceof BoostNode && (i === 0 || !nodes[i - 1].hasBoost)) {
        nodes[i] = toWord(nodes[i]);
      }
    }
  });
  return group;
}

/** Applies each boost marker to the node preceding it. */
function doBoost(parser, group) {
  const kept = [];
  for (let node of group.nodes) {
    if (node instanceof GroupNode) {
      node = doBoost(parser, node);
    } else if (node instanceof BoostNode) {
      const previous = kept[kept.length - 1];
      if (previous !== undefined && previous.hasBoost) {
        previous.setBoost(node.boost);
        continue;
      }
      node = toWord(node);
    }
    kept.push(node);
  }
  group.nodes = kept;
  return group;
}

/**
 * Builds the default plugin set: the taggers that recognise query syntax and
 * the filters that rewrite the node stream, each with its priority (lower
 * priorities run first).
 */
export function defaultPlugins() {
  const notOperator = new PrefixOperator("NOT", NotGroup);
  const andOperator = new InfixOperator("AND", AndGroup);
  const orOperator = new InfixOperator("OR", OrGroup);
  const andNotOperator = new InfixOperator("ANDNOT", AndNotGroup);
  const andMaybeOperator = new InfixOperator("ANDMAYBE", AndMaybeGroup);
  const requireOperator = new InfixOperator("REQUIRE", RequireGroup);

  const taggers = [
    [new WhitespaceTagger(), 100],
    [new SingleQuoteTagger(), 0],
    [new FieldsTagger(), 0],
    [new WildcardTagger(), 0],
    [new PhraseTagger(), 0],
    [new RangeTagger(), 1],
    [new OpenBracketTagger(), 0],
    [new CloseBracketTagger(), 0],
    [new OperatorTagger(`(^|(?<=(${SPACE_CLASS}|[()])))NOT(?=${SPACE_CLASS})`, notOperator), 0],
    [new OperatorTagger(`(?<=${SPACE_CLASS})AND(?=${SPACE_CLASS})`, andOperator), 0],
    [new OperatorTagger(`(?<=${SPACE_CLASS})OR(?=${SPACE_CLASS})`, orOperator), 0],
    [new OperatorTagger(`(?<=${SPACE_CLASS})ANDNOT(?=${SPACE_CLASS})`, andNotOperator), -5],
    [new OperatorTagger(`(?<=${SPACE_CLASS})ANDMAYBE(?=${SPACE_CLASS})`, andMaybeOperator), -5],
    [new OperatorTagger(`(^|(?<=${SPACE_CLASS}))REQUIRE(?=${SPACE_CLASS})`, requireOperator), 0],
    [new BoostTagger(), 0],
    [new EveryTagger(), -1],
  ];

  const filters = [
    [doGroups, 0],
    [cleanBoost, 0],
    [doWildcards, 50],
    [doFieldnames, 100],
    [removeWhitespace, 500],
    [doOperators, 600],
    [doBoost, 700],
  ];

  // The order the operators are listed in is their precedence order.
  const operators = [
    notOperator,
    andOperator,
    orOperator,
    andNotOperator,
    andMaybeOperator,
    requireOperator,
  ];

  return { taggers, filters, operators };
}

export { Operator, WordNode, AndGroup };

